"""matplotlib.gridspec — grid layout specification stubs."""

import sys as _sys


_gridspec_warned = set()

def _gridspec_getattr_fallback(self, name):
    if name.startswith('_'):
        raise AttributeError(name)
    key = f'{type(self).__name__}.{name}'
    if key not in _gridspec_warned:
        _gridspec_warned.add(key)
        try:
            _sys.__stderr__.write(
                f"[mpl-shim] gridspec.{key}() not implemented — returning None\n")
        except Exception:
            pass
    def _noop(*args, **kwargs): return None
    return _noop


class GridSpec:
    __getattr__ = _gridspec_getattr_fallback

    def __init__(self, nrows, ncols, figure=None, left=None, bottom=None,
                 right=None, top=None, wspace=None, hspace=None,
                 width_ratios=None, height_ratios=None):
        self.nrows = nrows
        self.ncols = ncols
        self.figure = figure
        self.left = left
        self.bottom = bottom
        self.right = right
        self.top = top
        self.wspace = wspace
        self.hspace = hspace
        self.width_ratios = width_ratios
        self.height_ratios = height_ratios

    def __getitem__(self, key):
        return SubplotSpec(self, key)

    def __iter__(self):
        for r in range(self.nrows):
            for c in range(self.ncols):
                yield SubplotSpec(self, (r, c))

    def __len__(self):
        return self.nrows * self.ncols

    def get_geometry(self):
        return (self.nrows, self.ncols)

    def get_grid_positions(self, fig, raw=False):
        """Return ``(bottoms, tops, lefts, rights)`` arrays in figure
        coordinates. Honours width/height ratios and inset margins."""
        import numpy as _np
        # Honour width_ratios — compute cumulative weight, normalize to
        # [left, right] inset.
        left   = self.left   if self.left   is not None else 0.125
        right  = self.right  if self.right  is not None else 0.9
        bottom = self.bottom if self.bottom is not None else 0.11
        top    = self.top    if self.top    is not None else 0.88
        wspace = self.wspace if self.wspace is not None else 0.2
        hspace = self.hspace if self.hspace is not None else 0.2

        wr = (_np.asarray(self.width_ratios, dtype=float)
              if self.width_ratios is not None
              else _np.ones(self.ncols))
        hr = (_np.asarray(self.height_ratios, dtype=float)
              if self.height_ratios is not None
              else _np.ones(self.nrows))
        wr = wr / wr.sum()
        hr = hr / hr.sum()

        # Carve out the (right-left) span minus inter-column gaps.
        avail_w = (right - left) / max(1.0,
            1.0 + wspace * (self.ncols - 1) / max(wr.mean(), 1e-9))
        # Simpler accurate calc: distribute proportionally to width_ratios.
        # Effective width per unit-ratio:
        gap_w = wspace * avail_w / max(self.ncols, 1)
        total_w = (right - left) - gap_w * (self.ncols - 1)
        col_widths = wr * total_w
        lefts = _np.zeros(self.ncols); rights = _np.zeros(self.ncols)
        x = left
        for i in range(self.ncols):
            lefts[i] = x
            rights[i] = x + col_widths[i]
            x = rights[i] + gap_w

        gap_h = hspace * (top - bottom) / max(self.nrows, 1)
        total_h = (top - bottom) - gap_h * (self.nrows - 1)
        row_heights = hr * total_h
        # Rows numbered top-to-bottom (row 0 is at top).
        tops = _np.zeros(self.nrows); bottoms = _np.zeros(self.nrows)
        y = top
        for i in range(self.nrows):
            tops[i] = y
            bottoms[i] = y - row_heights[i]
            y = bottoms[i] - gap_h
        return bottoms, tops, lefts, rights

    def get_width_ratios(self):  return self.width_ratios
    def get_height_ratios(self): return self.height_ratios
    def set_width_ratios(self, w):  self.width_ratios = w
    def set_height_ratios(self, h): self.height_ratios = h

    def get_subplot_params(self, figure=None):
        """Return a :class:`SubplotParams` filled from this grid's
        inset/spacing values (defaults applied when unset)."""
        return SubplotParams(
            left=self.left, bottom=self.bottom,
            right=self.right, top=self.top,
            wspace=self.wspace, hspace=self.hspace)

    def subplots(self, *, sharex=False, sharey=False, squeeze=True, subplot_kw=None):
        from matplotlib import pyplot as _plt
        return _plt.subplots(self.nrows, self.ncols, sharex=sharex,
                              sharey=sharey, squeeze=squeeze,
                              subplot_kw=subplot_kw)

    def update(self, **kwargs):
        for k, v in kwargs.items():
            if hasattr(self, k):
                setattr(self, k, v)

    def tight_layout(self, figure, renderer=None, pad=1.08, h_pad=None,
                      w_pad=None, rect=None):
        """Apply a tight-layout pass to ``figure``. The plotly backend
        manages layout itself; we delegate to pyplot's
        ``tight_layout()`` so the figure margins still get tightened."""
        try:
            from matplotlib import pyplot as _plt
            _plt.tight_layout(pad=pad, h_pad=h_pad, w_pad=w_pad, rect=rect)
        except Exception:
            pass

    def locally_modified_subplot_params(self):
        """Return the names of subplot-params that have been set on this
        grid (non-default values). Mirrors upstream."""
        return [k for k in ('left', 'bottom', 'right', 'top', 'wspace', 'hspace')
                if getattr(self, k) is not None]


class GridSpecFromSubplotSpec(GridSpec):
    def __init__(self, nrows, ncols, subplot_spec, wspace=None, hspace=None,
                 width_ratios=None, height_ratios=None):
        super().__init__(nrows, ncols)
        self.subplot_spec = subplot_spec


class SubplotSpec:
    def __init__(self, gridspec, key):
        self._gridspec = gridspec
        self._key = key

    def get_gridspec(self):
        return self._gridspec

    def subgridspec(self, nrows, ncols, **kwargs):
        return GridSpecFromSubplotSpec(nrows, ncols, self, **kwargs)


# ─── Added: missing public names from upstream gridspec.py ─────────


class GridSpecBase:
    """Base class shared by :class:`GridSpec` and
    :class:`GridSpecFromSubplotSpec`. Stores the geometry primitives and
    answers the standard ``__getitem__`` queries."""

    def __init__(self, nrows, ncols, width_ratios=None, height_ratios=None):
        self._nrows = int(nrows)
        self._ncols = int(ncols)
        self._row_height_ratios = height_ratios
        self._col_width_ratios = width_ratios

    def get_geometry(self):
        return self._nrows, self._ncols

    @property
    def nrows(self):
        return self._nrows

    @property
    def ncols(self):
        return self._ncols

    def get_width_ratios(self):
        return self._col_width_ratios

    def set_width_ratios(self, width_ratios):
        self._col_width_ratios = width_ratios

    def get_height_ratios(self):
        return self._row_height_ratios

    def set_height_ratios(self, height_ratios):
        self._row_height_ratios = height_ratios

    def get_grid_positions(self, fig):
        """Return ``(bottoms, tops, lefts, rights)`` arrays. Without a
        real figure layout engine, we return a uniform grid in the
        figure's [0, 1] coordinate range."""
        import numpy as _np
        rows = _np.linspace(0, 1, self._nrows + 1)
        cols = _np.linspace(0, 1, self._ncols + 1)
        return rows[:-1], rows[1:], cols[:-1], cols[1:]


# Cannot reassign GridSpec.__bases__ — CPython rejects it because the
# deallocators differ. Register GridSpec / GridSpecFromSubplotSpec as
# virtual subclasses of GridSpecBase via ABCMeta so isinstance() still
# resolves correctly.
import abc as _abc
GridSpecBase = _abc.ABCMeta('GridSpecBase', (object,),
                             dict(GridSpecBase.__dict__))
GridSpecBase.register(GridSpec)
GridSpecBase.register(GridSpecFromSubplotSpec)


# ─── Added: SubplotParams from upstream gridspec.py ────────────────


class SubplotParams:
    """Tracks the inset that :func:`subplots_adjust` controls — the
    distances from the figure edge to each subplot edge, plus the
    spacing between subplots (``wspace`` / ``hspace``)."""

    def __init__(self, left=None, bottom=None, right=None, top=None,
                 wspace=None, hspace=None):
        self.left   = left   if left   is not None else 0.125
        self.bottom = bottom if bottom is not None else 0.11
        self.right  = right  if right  is not None else 0.9
        self.top    = top    if top    is not None else 0.88
        self.wspace = wspace if wspace is not None else 0.2
        self.hspace = hspace if hspace is not None else 0.2
        self.validate = True

    def update(self, left=None, bottom=None, right=None, top=None,
               wspace=None, hspace=None):
        if left   is not None: self.left = left
        if bottom is not None: self.bottom = bottom
        if right  is not None: self.right = right
        if top    is not None: self.top = top
        if wspace is not None: self.wspace = wspace
        if hspace is not None: self.hspace = hspace

    def to_dict(self):
        return dict(left=self.left, bottom=self.bottom, right=self.right,
                    top=self.top, wspace=self.wspace, hspace=self.hspace)


# ─── Added: SubplotSpec methods ─────────────────────────────────────


def _ss_get_geometry(self):
    gs = self._gridspec
    nrows, ncols = gs.nrows, gs.ncols
    if isinstance(self._key, slice):
        start, stop, _ = self._key.indices(nrows * ncols)
    else:
        start = stop = self._key
    return nrows, ncols, start, stop


def _ss_get_position(self, fig, return_all=False):
    """Return the (figLeft, figBottom, figWidth, figHeight) tuple
    occupied by this subplot, computed from the parent gridspec's
    width/height ratios and inset margins."""
    gs = self._gridspec
    nrows, ncols, start, stop = self.get_geometry()
    bottoms, tops, lefts, rights = gs.get_grid_positions(fig)
    # Figure out the row/col span.
    r0, r1 = start // ncols, stop // ncols
    c0, c1 = start % ncols, stop % ncols
    figLeft   = float(lefts[c0])
    figRight  = float(rights[c1])
    figTop    = float(tops[r0])
    figBottom = float(bottoms[r1])
    pos = (figLeft, figBottom, figRight - figLeft, figTop - figBottom)
    if return_all:
        return pos, (figLeft, figBottom, figRight, figTop)
    return pos


def _ss_get_topmost_subplotspec(self):
    return self


def _ss_is_first_row(self):
    nrows, ncols, start, stop = self.get_geometry()
    return start // ncols == 0
def _ss_is_last_row(self):
    nrows, ncols, start, stop = self.get_geometry()
    return start // ncols == nrows - 1
def _ss_is_first_col(self):
    nrows, ncols, start, stop = self.get_geometry()
    return start % ncols == 0
def _ss_is_last_col(self):
    nrows, ncols, start, stop = self.get_geometry()
    return start % ncols == ncols - 1
def _ss_rowspan(self):
    nrows, ncols, start, stop = self.get_geometry()
    return range(start // ncols, stop // ncols + 1)
def _ss_colspan(self):
    nrows, ncols, start, stop = self.get_geometry()
    return range(start % ncols, stop % ncols + 1)
def _ss_num1(self):
    return self.get_geometry()[2]
def _ss_num2(self):
    return self.get_geometry()[3]


SubplotSpec.get_geometry            = _ss_get_geometry
SubplotSpec.get_position            = _ss_get_position
SubplotSpec.get_topmost_subplotspec = _ss_get_topmost_subplotspec
SubplotSpec.is_first_row            = _ss_is_first_row
SubplotSpec.is_last_row             = _ss_is_last_row
SubplotSpec.is_first_col            = _ss_is_first_col
SubplotSpec.is_last_col             = _ss_is_last_col
SubplotSpec.rowspan                 = property(_ss_rowspan)
SubplotSpec.colspan                 = property(_ss_colspan)
SubplotSpec.num1                    = property(_ss_num1)
SubplotSpec.num2                    = property(_ss_num2)


# ─── Added: GridSpecBase final helpers ──────────────────────────────


def _gsb_get_subplot_params(self, figure=None):
    return SubplotParams()
def _gsb_new_subplotspec(self, loc, rowspan=1, colspan=1):
    return SubplotSpec(self, loc)
def _gsb_subplots(self, *, sharex=False, sharey=False,
                    squeeze=True, subplot_kw=None):
    from matplotlib import pyplot as plt
    return plt.subplots(self._nrows, self._ncols)[1]

# attach to the original GridSpecBase (the dict-based ABCMeta'd one
# pointed at by GridSpecBase after our earlier rewiring).
GridSpecBase.get_subplot_params = _gsb_get_subplot_params
GridSpecBase.new_subplotspec    = _gsb_new_subplotspec
GridSpecBase.subplots           = _gsb_subplots


# `get_subplot_params` and `locally_modified_subplot_params` are now
# real methods on the GridSpec class above. `GridSpecFromSubplotSpec`
# inherits both from GridSpec. `get_topmost_subplotspec` is inherited
# via SubplotSpec on the parent subplot_spec.
def _gsfss_get_topmost_subplotspec(self):
    """Walk parent SubplotSpecs to find the outermost one (mirrors
    upstream's GridSpecFromSubplotSpec.get_topmost_subplotspec)."""
    ss = self.subplot_spec
    while True:
        outer = getattr(ss._gridspec, 'subplot_spec', None)
        if outer is None:
            return ss
        ss = outer

GridSpecFromSubplotSpec.get_topmost_subplotspec = _gsfss_get_topmost_subplotspec
